public static int maxRegions(int N) {
    // Base case: if N is 0 or 1, there is only 1 region
    if (N <= 1) {
        return 1;
    }

    // Recursive case: divide the plane into 2 smaller planes
    // and calculate the maximum number of regions of each plane
    int left = maxRegions(N / 2);
    int right = maxRegions(N / 2);

    // Return the maximum of the two regions
    return Math.max(left, right);
}

