public double trimMean(int[] arr) {
	// Calculate the smallest 5% and largest 5% of the elements
	int[] sortedArr = arr.clone();
	Arrays.sort(sortedArr);
	int minIndex = (int) (sortedArr.length * 0.05);
	int maxIndex = sortedArr.length - minIndex - 1;
	Double[] quantiles = new Double[]{0.05, 0.95};
	Double[] bounds = DataFrameMath.whichQuantiles(sortedArr, minIndex, maxIndex, quantiles);

	// Calculate the mean of the remaining elements
	int sum = 0;
