	for (int i = minIndex; i < maxIndex; i++) {
		sum += sortedArr[i];
		count++;
	}
	return (double) sum / count;
}

private static double trimMean(int[] arr) {
  // Sort the array in non-decreasing order
  Arrays.sort(arr);

  // Calculate the median
  int median = (arr.length - 1) / 2;

  // Calculate the total number of elements to remove
  int lowerPercent = (int) (arr.length * 0.05);
  int upperPercent = (int) (arr.length * 0.05);

  // Calculate the sum of the remaining elements
  int sum = 0;
  for (int i = lowerPercent; i < arr.length - upperPercent; i++) {
    sum += arr[i];
  }

  // Calculate the mean
  double mean = (double) sum / (arr.length - 2 * lowerPercent);

  return mean;
}

public double trimMean(int[] arr) {
    // Step 1: Find the smallest 5% and largest 5% of the elements
    Arrays.sort(arr);
    int smallest5Percent = (int)(arr.length * 0.05);
    int largest5Percent = (int)(arr.length * 0.05);
    int sum = 0;
    for (int i = 0; i < smallest5Percent; i++) {
        sum += arr[i];
    }
    for (int i = arr.length - largest5Percent; i < arr.length; i++) {
        sum += arr[i];
    }

    // Step 2: Calculate the mean of the remaining elements
    int mean = sum / (arr.length - 2 * smallest5Percent);

    // Step 3: Return the mean with an error tolerance of 10^-5
    return Math.rint(mean * 100000) / 100000;
}

public double trimMean(int[] arr) {
    // Calculate the 5% discarding threshold
    int threshold = (int) (arr.length / 20);

    // Sort the array in descending order
    Arrays.sort(arr, Collections.reverseOrder());

    // Ignore the smallest 5% and largest 5% elements
    int start = threshold;
    int end = arr.length - threshold - 1;

    // Calculate the sum of the remaining elements
    int sum = 0;
    for (int i = start; i < end; i++) {
        sum += arr[i];
    }

    // Return the mean with an error within 10^-5
    return (double) sum /((end - start) + 1) * 1e5;
}

public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Calculate the mean of the top 90% of the elements
    int topElements = (int) (arr.length * 0.9);
    double meanTopElements = 0;
    for (int i = 0; i < topElements; i++) {
        meanTopElements += arr[i];
    }
    meanTopElements /= topElements;

    // Calculate the mean of the bottom 90% of the elements
    int bottomElements = (int) (arr.length * 0.9);
    double meanBottomElements = 0;
    for (int i = arr.length - 1; i >= arr.length - bottomElements; i--) {
        meanBottomElements += arr[i];
    }
    meanBottomElements /= bottomElements;

    // Return the trim mean with an error of 10^-5
    return (meanTopElements + meanBottomElements) / 2;
}

public static boolean canArrange(int[] arr, int k) {
