    int n = arr.length;
    int[] sum = new int[n];
    for (int i = 0; i < n; i++) {
        sum[i] = arr[i];
        for (int j = i + 1; j < n; j++) {
            sum[i] += arr[j];
        }
    }
    for (int i = 0; i < n; i++) {
        if (sum[i] % k == 0) return true;
    }
    return false;
}

