public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Idea: perform a breadth-first search (BFS) of the tree,
    // keeping track of the time and the number of apples collected.
    // Return the minimum time required to collect all the apples.

    // Initialize a queue to keep track of the nodes to visit
    Queue<Integer> queue = new LinkedList<>();

    // Initialize a set to keep track of the visited nodes
    Set<Integer> visited = new HashSet<>();

    // Initialize the time and the number of apples collected
    int time = 0, apples = 0;

    // Add the starting node to the queue
    queue.offer(0);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the size of the current level
        int levelSize = queue.size();

        // Loop through the nodes in the current level
        for (int i = 0; i < levelSize; i++) {
            // Get the node to visit
            int node = queue.poll();

            // If the node has not been visited, mark it as visited and add it to the set
            if (!visited.contains(node)) {
                visited.add(node);
            }

            // If the node has an apple, collect it and increase the number of apples
            if (hasApple[node]) {
                apples++;
            }

            // If the node has children, add them to the queue
            if (node * 2 + 1 < n) {
                queue.offer(node * 2 + 1);
            }
            if (node * 2 + 2 < n) {
                queue.offer(node * 2 + 2);
            }
        }

        // Increment the time and check if the number of apples is equal to the total number of apples
        time++;
        if (apples == n) {
            return time;
        }
    }

    // If all apples are not collected, return -1
    return -1;
}

private int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Do DFS from node 0 and keep track of the minimum time required to reach node 0
    // while collecting all the apples along the way
    int[] dist = new int[n];
    Arrays.fill(dist, -1);
    dist[0] = 0;
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
    pq.offer(new int[] {0, 0});
    while (!pq.isEmpty()) {
        int[] curr = pq.poll();
        int node = curr[0];
        int time = curr[1];
        if (dist[node] != -1 && dist[node] <= time) continue;
        dist[node] = time;
        // If the current node has an apple, add its weight to the time
        if (hasApple[node]) time += node;
        // Iterate through the neighbors of the current node and enqueue them
        for (int[] edge : edges[node]) {
            int neighbor = edge[0] == node ? edge[1] : edge[0];
            if (dist[neighbor] == -1) {
                pq.offer(new int[] {neighbor, time + 1});
            }
        }
    }
    // Return the minimum time required to collect all the apples and return to node 0
    return dist[0];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Create an graph and initialize the distance from node 0 to all other nodes as infinite
    Graph graph = new Graph(n);
    for (int[] edge : edges) {
        graph.addEdge(edge[0], edge[1]);
        graph.addEdge(edge[1], edge[0]);
    }
    int[] dist = new int[n];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[0] = 0;

    // Use BFS to find the distance from node 0 to all other nodes
    Queue<Integer> queue = new LinkedList<>();
    queue.add(0);
    while (!queue.isEmpty()) {
        int curr = queue.poll();
        if (hasApple[curr]) {
            return dist[curr];
        }
        for (int neighbor : graph.adjacencyList.get(curr)) {
            if (dist[neighbor] == Integer.MAX_VALUE) {
                dist[neighbor] = dist[curr] + 1;
                queue.add(neighbor);
            }
        }
    }
    return dist[0];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a 2D array dp to store the minimum time to collect apples at each node
    int[][] dp = new int[n][n];

    // Set the base case: the time to collect apples at node 0 is 0
    dp[0][0] = 0;

    // Loop through each node and its neighbors
    for (int node = 0; node < n; node++) {
        for (int neighbor : edges[node]) {
            // If the current node has an apple, the time to collect it is 1
            if (hasApple[node]) {
                dp[node][neighbor] = 1;
            // Otherwise, the time to collect apples at the current node is the maximum of the time to collect apples at its neighbors plus 1
            } else {
                dp[node][neighbor] = Math.max(dp[node][neighbor], dp[neighbor][neighbor] + 1);
            }
        }
    }

    // Return the minimum time to collect all apples
    return Arrays.stream(dp[0]).min().orElse(Integer.MAX_VALUE);
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize an array to store the time required at each node
    int[] times = new int[n];
    for (int i = 0; i < n; i++) {
        times[i] = -1;
    }

    // Start with the node 0, with a time of 0
    times[0] = 0;

    // Loop until all nodes have been visited
    while (true) {
        // Check if all nodes have been visited
        boolean allVisited = true;
        for (int i = 0; i < n; i++) {
            if (times[i] == -1) {
                allVisited = false;
                break;
            }
        }
        if (allVisited) {
            break;
        }

        // Find the node with the minimum time
        int minTime = Integer.MAX_VALUE;
        int minNode = -1;
        for (int i = 0; i < n; i++) {
            if (times[i] != -1) {
                continue;
            }
            if (hasApple[i] && times[i] < minTime) {
                minTime = times[i];
                minNode = i;
            }
        }

        // If there is no node with an apple, break
        if (minNode == -1) {
            break;
        }

        // Update the times for the adjacent nodes
        for (int i = 0; i < edges[minNode].length; i++) {
            int adjNode = edges[minNode][i];
            if (times[adjNode] == -1) {
                times[adjNode] = minTime + 1;
            }
        }
    }

    // Return the minimum time required to collect all apples
    int minTimeRequired = Integer.MAX_VALUE;
    for (int i = 0; i < n; i++) {
        if (hasApple[i] && times[i] < minTimeRequired) {
            minTimeRequired = times[i];
        }
    }
    return minTimeRequired;
}

public String sortString(String s) {
    int n = s.length();
    char[] arr = new char[n];
    int smallest = -1, largest = -1;
    String result = "";
    for (int i = 0; i < n; i++) {
        if (smallest == -1 || s.charAt(i) < smallest) {
            smallest = s.charAt(i);
        }
        if (largest == -1 || s.charAt(i) > largest) {
            largest = s.charAt(i);
        }
    }
    while (result.length() < n) {
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c == smallest && result.indexOf(c) == -1) {
                result += c;
                smallest++;
                break;
            }
        }
        for (int i = n-1; i >= 0; i--) {
            char c = s.charAt(i);
            if (c == largest && result.indexOf(c) == -1) {
                result += c;
                largest--;
                break;
            }
        }
    }
    return result;
}

public String sortString(String s) {
    String result = "";

    while (s.length() > 0) {
        char smallest = s.charAt(0);
        int smallestIndex = 0;

        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) < smallest) {
                smallest = s.charAt(i);
                smallestIndex = i;
            }
        }

        result += smallest;
        s = s.substring(0, smallestIndex) + s.substring(smallestIndex + 1);

        char largest = s.charAt(s.length() - 1);
        int largestIndex = s.length() - 1;

        for (int i = s.length() - 2; i >= 0; i--) {
            if (s.charAt(i) > largest) {
                largest = s.charAt(i);
                largestIndex = i;
            }
        }

        result += largest;
        s = s.substring(0, largestIndex) + s.substring(largestIndex + 1);
    }

    return result;
}

