public boolean splitArraySameAverage(int[] nums) {
  int sum = 0;

  // Calculate the sum of the input array
  for (int num : nums) {
    sum += num;
  }

  // Find the average of the input array
  int average = sum / nums.length;

  // Initialize two variables to keep track of the sum of the first half and the second half of the array
  int firstHalfSum = 0;
  int secondHalfSum = 0;

  // Split the input array into two halves
  for (int i = 0; i < nums.length / 2; i++) {
    firstHalfSum += nums[i];
  }

  // Find the sum of the second half of the array
  for (int i = nums.length / 2; i < nums.length; i++) {
    secondHalfSum += nums[i];
  }

  // Check if the average is the same for the two halves
  return firstHalfSum / (nums.length / 2) == average && secondHalfSum / (nums.length / 2) == average;
}

public boolean splitArraySameAverage(int[] nums) {

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    int avg = sum / nums.length;
    int leftSum = 0, rightSum = 0;

    for (int i = 0; i < nums.length; i++) {
        if (leftSum == avg) {
            rightSum += nums[i];
        } else if (rightSum == avg) {
            leftSum += nums[i];
        } else if (leftSum < avg && rightSum < avg) {
            leftSum += nums[i];
        } else if (leftSum > avg && rightSum > avg) {
            rightSum += nums[i];
        }
    }

    return leftSum == avg && rightSum == avg;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    int[] dp = new int[cost.length];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < cost.length; i++) {
        dp[i] = Math.min(dp[i-1], dp[i-2]) + cost[i];
    }
    return Math.min(dp[cost.length-1], dp[cost.length-2]);
}

public int minCostClimbingStairs(int[] cost) {
    int minCost = 0;
    for (int i = 1; i < cost.length; i++) {
        minCost = Math.min(minCost, cost[i - 1] + cost[i]);
    }
    return minCost;
}

public int minCostClimbingStairs(int[] cost) {
int dp0 = 0, dp1 = 0, dp2 = 0;
for (int i = 0; i < cost.length; i++) {
dp2 = Math.min(dp0, dp1) + cost[i];
dp0 = dp1;
dp1 = dp2;
}
return Math.min(dp0, dp1);
}

public int minCostClimbingStairs(int[] cost) {
    int minCost = Integer.MAX_VALUE;
    for (int i = 0; i < cost.length; i++) {
        int cost1 = i > 0 ? cost[i - 1] : 0;
        int cost2 = i < cost.length - 1 ? cost[i + 1] : 0;
        int costAtCurrentStep = cost[i] + Math.min(cost1, cost2);
        if (costAtCurrentStep < minCost) {
            minCost = costAtCurrentStep;
        }
    }
    return minCost;
}

