public boolean hasAllCodes(String s, int k) {
    for (int i = 0; i < 2^k; i++) {
        String substring = s.substring(i * k, (i + i) % s.length());
        if (!substring.matches("0" * k)) {
            return false;
        }
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
  // Initialize a boolean variable to keep track of whether all codes are present
  boolean hasAllCodes = true;

  // Loop through each substring of length k in the input string
  for (int i = 0; i <= s.length() - k; i++) {
    // Check if the current substring is present in the input string
    if (!s.contains(s.substring(i, i + k))) {
      // If the substring is not present, set the hasAllCodes variable to false and break the loop
      hasAllCodes = false;
      break;
    }
  }

  // Return the value of the hasAllCodes variable
  return hasAllCodes;
}

public boolean hasAllCodes(String s, int k) {
if(s.length() < k) {
return false;
}
Set<String> substrings = new HashSet<String>();
for(int i = 0; i < s.length() - k + 1; i++) {
substrings.add(s.substring(i, i + k));
}
return substrings.size() == (1 << k);
}

