public int minInsertions(String s) {
    Stack<Character> stack = new Stack<>();
    int count = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            stack.push(c);
        } else {
            if (stack.isEmpty()) {
                count++;
            } else {
                stack.pop();
            }
        }
    }
    while (!stack.isEmpty()) {
        stack.pop();
        count++;
    }
    return count;
}

