public int findMinFibonacciNumbers(int k) {
    int n = 0;
    while (k > 0) {
        if (k - (n * (n + 1)) / 2 > 0) {
            n++;
        } else {
            break;
        }
    }
    return n;
}

public int findMinFibonacciNumbers(int k) {
        if (k == 0) {
            return 0;
        }
        if (k == 1) {
            return 1;
        }

        int[] fib = new int[] {1, 1};
        int n = 2;
        while (fib[n - 1] + fib[n - 2] <= k) {
            fib[n++] = fib[n - 1] + fib[n - 2];
        }

        return n - (k - fib[n - 1] - fib[n - 2]) > k - fib[n - 1] - fib[n - 2] ? n - 1 : n;
    }

public static int findMinFibonacciNumbers(int k) {
        int[] fib = new int[] {1, 1};
        int count = 0;
        while (fib[count] < k) {
            fib[count + 1] = fib[count] + fib[count - 1];
            count++;
        }
        return count;
    }

private static int findMinFibonacciNumbers(int k) {
    if (k <= 1) {
        return 0;
    }

    int[] fib = new int[k];
    fib[0] = 1;
    fib[1] = 1;
    for (int i = 2; i < k; i++) {
        fib[i] = fib[i - 1] + fib[i - 2];
        if (fib[i] > k) {
            return i;
        }
    }

    return k;
}

public int findMinFibonacciNumbers(int k) {
    // Initialize a hash map to store the Fibonacci numbers and their indices
    Map<Integer, Integer> fibNumbers = new HashMap<>();
    fibNumbers.put(0, 0); // F0 = 0
    fibNumbers.put(1, 1); // F1 = 1
    int n = 2; // Initialize the number of Fibonacci numbers

    // Iterate until the sum of the Fibonacci numbers is greater than or equal to k
    while (fibNumbers.values().stream().reduce(0, Integer::sum) < k) {
        // Calculate the next Fibonacci number
        int fibNumber = fibNumbers.get(n - 1) + fibNumbers.get(n - 2);
        // Store the Fibonacci number and its index in the hash map
        fibNumbers.put(n, fibNumber);
        n++;
    }

    // Count the number of Fibonacci numbers needed to sum up to k
    int count = 0;
    for (int fibNumber : fibNumbers.values()) {
        if (fibNumber <= k) {
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    ArrayList<Integer> factors = new ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            if (i != n / i) {
                factors.add(n / i);
            }
        }
    }
    if (factors.size() < k) {
        return -1;
    } else {
        return factors.get(k - 1);
    }
}

