public int maxUniqueSplit(String s) {
        int max = 0;
        for (int i = s.length() - 1; i >= 1; i--) {
            for (int j = 0; j < i; j++) {
                String substr = s.substring(j, i) + s.substring(i, s.length());
                if (s.equals(substr)) {
                    max++;
                }
            }
        }
        return max;
    }

public int maxUniqueSplit(String s) {
        List<Character> uniqueChars = new ArrayList<>();
        for (char c : s.toCharArray()) {
            if (!uniqueChars.contains(c)) {
                uniqueChars.add(c);
            }
        }
        int count = 0;
        for (char c : uniqueChars) {
            int index = s.indexOf(c);
            while (index != -1) {
                count++;
                index = s.indexOf(c, index + 1);
            }
        }
        return count;
    }

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0 || s.length() == 1) {
        return 1;
    }

    int maxUniqueSubstrings = 0;
    for (int i = 1; i < s.length(); i++) {
        int count = 0;
        for (int j = 0; j < s.length(); j++) {
            if (s.charAt(j) == s.charAt(i)) {
                count++;
            }
        }
        maxUniqueSubstrings = Math.max(maxUniqueSubstrings, count);
    }
    return maxUniqueSubstrings;
}

public int maxUniqueSplit(String s) {
    // Initialize a hash table to keep track of unique substrings
    Set<String> uniqueSubstrings = new HashSet<>();

    // Loop through the string and split it at each character
    for (int i = 0; i < s.length(); i++) {
        String substring = s.substring(i);
        if (!uniqueSubstrings.contains(substring)) {
            uniqueSubstrings.add(substring);
        }
    }

    // Return the size of the hash table, which is the maximum number of unique substrings
    return uniqueSubstrings.size();
}

public int maxUniqueSplit(String s) {
    // Initialize a set to store unique substrings
    Set<String> uniqueSubstrings = new HashSet<>();
    // Initialize the maximum number of unique substrings as 0
    int maxUniqueSplit = 0;
    // Loop through each character of the input string
    for (int i = 0; i < s.length(); i++) {
        // Get the substring starting from the current character
        String substring = s.substring(i);
        // If the substring is not already in the set, add it and increment the maximum number of unique substrings
        if (!uniqueSubstrings.contains(substring)) {
            uniqueSubstrings.add(substring);
            maxUniqueSplit++;
        }
        // Get the substring ending at the current character
        substring = s.substring(0, i + 1);
        // If the substring is not already in the set, add it and increment the maximum number of unique substrings
        if (!uniqueSubstrings.contains(substring)) {
            uniqueSubstrings.add(substring);
            maxUniqueSplit++;
        }
    }
    // Return the maximum number of unique substrings
    return maxUniqueSplit;
}

public int minOperations(String[] logs) {
  int minOperations = 0;
  Stack<Integer> stack = new Stack<>();
for (String log : logs) {
// if log is "dX/" where X is a number, push X to stack
if (log.matches("^d[0-9]+/$")) {
stack.push(Integer.parseInt(log.substring(1, log.length() - 1)));
}
// if log is "../", pop from stack if not empty, decrease minOperations if not empty
else if (log.equals("../") && !stack.isEmpty()) {
stack.pop();
minOperations++;
}
}
return minOperations;
}

