public int minOperations(String[] logs) {
        // Iterate through the logs and build a stack to keep track of the current folder
        Stack<String> stack = new Stack<>();
        stack.push("/");
        int minOperations = 0;
        for (String log : logs) {
            // If the log is a folder, push it to the stack
            if (log.endsWith("/")) {
                stack.push(log.substring(0, log.length() - 1));
            }
            // If the log is a "back" operation (i.e., ".."), pop the top folder from the stack
            else if (log.equals("..")) {
                stack.pop();
            }
            // If the stack is empty, return 0 operations
            if (stack.isEmpty()) {
                return 0;
            }
        }
        // Return the minimum number of operations to return to the main folder
        return minOperations;
    }

public String getSmallestString(int n, int k) {
