    for (int i = 1; i <= n; i++) {
        s += (char) ('a' + k % 26);
        k /= 26;
    }
    return s;
}

public String getSmallestString(int n, int k) {
    // Initialize the result string with the first n-1 characters
    String result = "";
    for (int i = 0; i < n - 1; i++) {
        result += (char) ('a' + i);
    }

    // Add the last character to the string
    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum += (i + 1);
    }
    if (sum == k) {
        result += (char) ('a' + n - 1);
    } else if (sum < k) {
        result += (char) ('a');
    } else {
        result += (char) ('z' + (-k % 26));
    }

    return result;
}

