public String getSmallestString(int n, int k) {

        // Create a character array of length n
        char[] arr = new char[n];

        // Initialize the first character of the array to 'a'
        arr[0] = 'a';

        // Initialize the value of the first character to 1
        int value = 1;

        // Loop through the remaining characters of the array
        for (int i = 1; i < n; i++) {

            // If the value is less than the given k, use the next character
            if (value < k) {
                arr[i] = (char) (arr[i - 1] + 1);
                value += (arr[i - 1] + 1);
            }

            // If the value is greater than or equal to the given k, wrap around to the first character
            else {
                arr[i] = 'a';
                value = arr[i] + 1;
            }
        }

        // Return the string formed by the array
        return String.valueOf(arr);
    }

