public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNumbers = new ArrayList<>();
    for (int i = low; i <= high; i++) {
        boolean isSteppingNumber = true;
        int num = i;
        while (num > 0) {
            int digit = num % 10;
            if (digit == 0 || (digit > 1 && digit < 9) && (digit - 1 == (num / 10) % 10 || digit + 1 == (num / 10) % 10)) {
                //digit is a stepping digit move on to the next digit
                num /= 10;
                continue;
            } else {
                //digit is not a stepping digit
                isSteppingNumber = false;
                break;
            }
        }
        if (isSteppingNumber) {
            steppingNumbers.add(i);
        }
    }
    return steppingNumbers;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNumbers = new ArrayList<>();

    // Add the low number to the list of stepping numbers
    steppingNumbers.add(low);

    // Add the stepping numbers between low and high to the list
    for (int i = low + 1; i < high; i++) {
        String currentNumber = Integer.toString(i);
        char[] digits = currentNumber.toCharArray();
        for (int j = 0; j < digits.length; j++) {
            char digit = digits[j];
            if (digit == '9') {
                // If the digit is 9, make it a 0 for the next iteration
                digits[j] = '0';
            } else if (digit == '0') {
                // If the digit is 0, make it a 9 for the next iteration
                digits[j] = '9';
            } else {
                // If the digit is neither 0 nor 9, increment it
                digits[j] = (char) (digit + 1);
                break;
            }
        }
        int newNumber = Integer.parseInt(new String(digits));
        if (newNumber <= high) {
            steppingNumbers.add(newNumber);
        }
    }

    // Add the high number to the list of stepping numbers
    steppingNumbers.add(high);

    return steppingNumbers;
}

