public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;

    int result = 0;

    for (int i = 0; i < m; i++) {
        // Calculate the length of the longest line in each row
        int[] rowLength = new int[n];
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                rowLength[j] = 1;
                for (int k = j + 1; k < n; k++) {
                    if (mat[i][k] == 1) {
                        rowLength[k] = Math.max(rowLength[k], rowLength[k - 1] + 1);
                    }
                }
            }
        }

        // Calculate the length of the longest line in each column
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int colLength = 1;
                for (int k = j + 1; k < n; k++) {
                    if (mat[i][k] == 1) {
                        colLength = Math.max(colLength, rowLength[k] + 1);
                    }
                }
                result = Math.max(result, colLength);
            }
        }
    }

    return result;
}

public static int longestLine(int[][] mat) {
        int m = mat.length;
        int n = mat[0].length;
        int[][] dp = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (mat[i][j] == 1) {
                    dp[i][j] = 1;
                    if (i > 0 && j > 0 && mat[i - 1][j - 1] == 1) {
                        dp[i][j] += dp[i - 1][j - 1];
                    }
                    if (i > 0 && mat[i - 1][j] == 1) {
                        dp[i][j] = Math.max(dp[i][j], dp[i - 1][j]);
                    }
                    if (j > 0 && mat[i][j - 1] == 1) {
                        dp[i][j] = Math.max(dp[i][j], dp[i][j - 1]);
                    }
                }
            }
        }
        int max = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                max = Math.max(max, dp[i][j]);
            }
        }
        return max;
    }

public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int length = 0;

                for (int k = i; k < m; k++) {
                    if (mat[k][j] == 0) {
                        break;
                    }

                    length++;
                }

                maxLength = Math.max(maxLength, length);
            }
        }
    }

    return maxLength;
}

