public static int squarePermutations(int[] A) {
    int size = A.length;
    int[] B = new int[size];
    for (int i = 0; i < size; i++) {
        B[i] = A[i];
    }
    Arrays.sort(B);
    boolean[] visited = new boolean[size];
    int count = 0;
    for (int i = 0; i < size; i++) {
        if (!visited[i]) {
            count++;
            int j = i + 1;
            while (j < size && B[i] + B[j] * B[j] == B[j]) {
                visited[j] = true;
                j++;
            }
            if (j == size) {
                break;
            }
            i = j - 1;
        }
    }
    return count;
}

public static int squarePermutations(int[] A) {
    // Initialize a set to store the unique permutations
    Set<String> permutations = new HashSet<>();

    // Compute the sum of each pair of adjacent elements
    int[] sums = new int[A.length - 1];
    for (int i = 0; i < A.length - 1; i++) {
        sums[i] = A[i] + A[i + 1];
    }

    // Check if any sum is a perfect square
    for (int sum : sums) {
        if (Math.sqrt(sum) % 1 == 0) {
            // If a sum is a perfect square, add it to the set
            permutations.add(sum);
        }
    }

    // Compute the number of square permutations
    int count = 0;
    for (String permutation : permutations) {
        count += countPermutations(permutation.length());
    }

    return count;
}

