    for (int i = 0; i < A.length; i++) {
        for (int j = i + 1; j < A.length; j++) {
            if (A[i] + A[j] == Math.pow(A[i] * A[j], 0.5)) {
                set.add(A[i] * A[j]);
            }
        }
    }
    return set.size();
}

public static int squarePermutations(int[] A) {
    int[] B = A.clone();
    Arrays.sort(B);
    int N = B.length;
    int[] dp = new int[N];
    dp[0] = 1;
    for (int i = 1; i < N; i++) {
        if (B[i] == B[i - 1]) {
            dp[i] = dp[i - 1];
        } else {
            int j = i - 1;
            while (j >= 0 && B[i] - B[j] > 0) {
                j--;
            }
            if (j >= 0) {
                dp[i] = dp[j] + dp[i - j - 1];
            } else {
                dp[i] = dp[i - 1];
            }
        }
    }
    return dp[N - 1];
}

