public static boolean isBoomerang(int[][] points) {
    // Sort the points by their x-coordinate
    Arrays.sort(points, (p1, p2) -> p1[0] - p2[0]);

    // Calculate the differences between x-coordinates and y-coordinates
    int[] diffX = new int[points.length - 1];
    int[] diffY = new int[points.length - 1];
    for (int i = 1; i < points.length; i++) {
        diffX[i - 1] = points[i][0] - points[i - 1][0];
        diffY[i - 1] = points[i][1] - points[i - 1][1];
    }

    // Check if the differences between x-coordinates form an increasing sequence
    boolean increasingX = true;
    for (int i = 1; i < diffX.length; i++) {
        if (diffX[i] <= diffX[i - 1]) {
            increasingX = false;
            break;
        }
    }

    // Check if the differences between y-coordinates form a decreasing sequence
    boolean decreasingY = true;
    for (int i = 1; i < diffY.length; i++) {
        if (diffY[i] >= diffY[i - 1]) {
            decreasingY = false;
            break;
        }
    }

    // Return true if the differences between x-coordinates form an increasing sequence, and
    // the differences between y-coordinates form a decreasing sequence
    return increasingX && decreasingY;
}

public static boolean isBoomerang(int[][] points) {
  // Calculate the determinant of the matrix using the Laplace expansion formula
  int det = points[0][0] * (points[1][1] * points[2][2] - points[1][2] * points[2][1])
        - points[0][1] * (points[1][0] * points[2][2] - points[1][2] * points[2][0])
        + points[0][2] * (points[1][0] * points[2][1] - points[1][1] * points[2][0]);
  // Return true if the determinant is negative, which means the points form a boomerang
  return det < 0;
}

public static int findNthUglyNumber(int n) {
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    for (int i = 1; i < n; i++) {
        int nextUglyNumber = Math.min(Math.min(uglyNumbers[i2] * 2, uglyNumbers[i3] * 3), uglyNumbers[i5] * 5);
        uglyNumbers[i] = nextUglyNumber;
        if (nextUglyNumber == uglyNumbers[i2] * 2) i2++;
        if (nextUglyNumber == uglyNumbers[i3] * 3) i3++;
        if (nextUglyNumber == uglyNumbers[i5] * 5) i5++;
    }
    return uglyNumbers[n - 1];
}

