    Queue<Integer> que = new LinkedList<Integer>();
    que.offer(1);
    int count = 1;
    while (count != n) {
        int curr = que.poll();
        if (curr != 1) {
            que.offer(curr / 2);
            if (curr % 3 != 0) {
                que.offer(curr * 3);
            }
        }
        count++;
    }
    return que.poll();
