public static int findNthUglyNumber(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("The order must be a non-negative integer.");
    }

    int[] primes = {2, 3, 5};

    int[] factors = new int[primes.length + 1];
    factors[0] = 1;

    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        int index = 0;
        for (int j = 1; j <= primes.length; j++) {
            int factor = factors[j - 1] * primes[j - 1];
            if (factor < min && factor % factors[j] == 0) {
                min = factor;
                index = j;
            }
        }
        factors[index]++;
    }
    return factors[primes.length];
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer.");
    }

    int[] factors = {1, 2, 3, 5};
    List<Long> numbers = new ArrayList<>(n);
    numbers.add(1L);

    for (int i = 1; i < n; i++) {
        long min = Long.MAX_VALUE;
        for (int factor : factors) {
            min = Math.min(min, numbers.get(i - 1) * factor);
        }
        numbers.add(min);
    }

    return numbers.get(n - 1).intValue();
}

public static int findNthUglyNumber(int n) {
    // Initialize a queue to store the candidate numbers
    Queue<Integer> queue = new LinkedList<>();
    // Initialize the first 10 ugly numbers
    for (int i = 1; i <= 10; i++) {
        queue.offer(i);
    }
    // Loop until the size of the queue is equal to n
    while (queue.size() < n) {
        // Extract the current smallest number from the queue
        int current = queue.poll();
        // Add the next 10 ugly numbers to the queue
        for (int i = 1; i <= 10; i++) {
            queue.offer(current * 2);
            queue.offer(current * 3);
            queue.offer(current * 5);
        }
    }
    // Return the nth ugly number
    return queue.poll();
}

